import{_ as r,o as a,c as t,ae as o}from"./chunks/framework.DCJ5T8RY.js";const c=JSON.parse('{"title":"[LeetCode 88] Merge Sorted Array","description":"","frontmatter":{"title":"[LeetCode 88] Merge Sorted Array","date":"2019-02-12"},"headers":[],"relativePath":"2019/leetcode-88-merge-sorted-array.md","filePath":"2019/leetcode-88-merge-sorted-array.md","lastUpdated":1786185344000}'),s={name:"2019/leetcode-88-merge-sorted-array.md"};function n(i,e,l,d,m,u){return a(),t("div",null,[...e[0]||(e[0]=[o('<p>Given two sorted integer arrays nums1 and nums2, merge nums2 into nums1 as one sorted array.</p><p>Note:</p><p>The number of elements initialized in nums1 and nums2 are m and n respectively. You may assume that nums1 has enough space (size that is greater or equal to m + n) to hold additional elements from nums2.</p><h3 id="题目类型分析" tabindex="-1">题目类型分析 <a class="header-anchor" href="#题目类型分析" aria-label="Permalink to &quot;题目类型分析&quot;">​</a></h3><p>Merge Sort 算法题目，尽可能往这个方向上考虑具体思路。<br> 如果不能第一时间想到 Merge Sort 说明数据结构和算法基础需要复习，补好基础继续解题才是正确的路。</p><h3 id="解法" tabindex="-1">解法 <a class="header-anchor" href="#解法" aria-label="Permalink to &quot;解法&quot;">​</a></h3><p>现有条件相当于 merge sort 剩最后 2 个子数组，直接比较各自元素再 merge 。<br><strong>题目有限制，要求直接修改 nums1，如果使用额外空间会报错</strong>，需要对合并步骤做一些调整。 题目说明 nums1 长度足够，从数组尾部开始，从后往前向 nums1 中复制元素就可以了，步骤如下：</p><ul><li>比较 nums1 和 nums2 初始尾部元素大小，大的那个移动到 nums1 未使用的尾部</li><li>重复以上步骤，依次把二个子数组当前最大元素复制到 nums1 的尾部，直至二者其中之一所有元素都已复制</li><li>因为是将 nums2 元素合并到 nums1 中，所以只需要考虑剩余数组是 nums2 的情况，继续赋值 nums2 的元素，直至将 nums1 数组填满</li><li>新的 nums1 就是合并后的结果，结束</li></ul><h3 id="类似题目" tabindex="-1">类似题目 <a class="header-anchor" href="#类似题目" aria-label="Permalink to &quot;类似题目&quot;">​</a></h3><p>不同数据结构的类似题目</p><ol><li>[LeetCode 21] Merge Two Sorted List</li><li>[LeetCode 617] Merge Two Binary Trees</li></ol>',11)])])}const h=r(s,[["render",n]]);export{c as __pageData,h as default};
